import { useState } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { Link, Route, Switch, useLocation } from 'wouter';
import {
  Activity, AlertTriangle, ArrowDownRight, ArrowUpRight, BarChart3, Bell, Boxes, Check,
  ChevronRight, CircleDot, Clock3, CloudSun, Database, Gauge, GitBranch, Leaf, Menu,
  PackageCheck, RefreshCw, Route as RouteIcon, ScanLine, Settings2, ShieldCheck,
  SlidersHorizontal, Sparkles, Thermometer, Truck, Users, X, Zap,
} from 'lucide-react';
import {
  getGetActivityQueryKey, getGetAlertsQueryKey, getGetForecastsQueryKey, getGetInventoryQueryKey,
  getGetOverviewQueryKey, getGetPartnersQueryKey, getGetRoutesQueryKey, getGetStorageZonesQueryKey,
  getGetSustainabilityQueryKey, getGetSurplusMatchesQueryKey, getGetSurplusQueryKey,
  useAcceptSurplusMatch, useCreateInventory, useCreateSurplus, useGenerateForecast,
  useGetActivity, useGetAlerts, useGetForecasts, useGetInventory, useGetOverview, useGetPartners,
  useGetRoutes, useGetStorageZones, useGetSustainability, useGetSurplus, useGetSurplusMatches,
  useOptimizeRoute, useResetDemo, useScanInventoryQuality, useSimulateDemo,
  useSimulateStorageUpdate, useUpdateAlert, useUpdateInventory, useUpdateSurplus,
} from '@workspace/api-client-react';
import { DemoInputAction } from '@workspace/api-client-react';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();
const nav = [
  { href: '/', label: 'Command center', icon: Gauge },
  { href: '/forecast', label: 'Demand forecast', icon: BarChart3 },
  { href: '/inventory', label: 'Inventory & quality', icon: Boxes },
  { href: '/surplus', label: 'Surplus network', icon: GitBranch },
  { href: '/logistics', label: 'Pickup routes', icon: Truck },
  { href: '/operations', label: 'Processing lines', icon: Activity },
  { href: '/sustainability', label: 'Impact analytics', icon: Leaf },
  { href: '/alerts', label: 'Alerts', icon: Bell },
  { href: '/settings', label: 'Demo controls', icon: Settings2 },
];

const money = (n = 0) => new Intl.NumberFormat('en-IN', { maximumFractionDigits: 0 }).format(n);
const compact = (n = 0) => Intl.NumberFormat('en-IN', { notation: 'compact', maximumFractionDigits: 1 }).format(n);
const day = (v?: string) => v ? new Date(v).toLocaleDateString('en-IN', { day: '2-digit', month: 'short' }) : '—';
const time = (v?: string) => v ? new Date(v).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' }) : '—';
const tone = (value = '') => value.toLowerCase().includes('critical') || value.toLowerCase().includes('high') ? 'danger' : value.toLowerCase().includes('warn') || value.toLowerCase().includes('medium') ? 'warn' : 'good';
const greeting = () => {
  const hour = new Date().getHours();
  return hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening';
};
const currentDateLabel = () => new Intl.DateTimeFormat('en-IN', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(new Date());

function Loading({ lines = 4 }: { lines?: number }) {
  return <div className="space-y-3" data-testid="state-loading">{Array.from({ length: lines }).map((_, i) => <div key={i} className="skeleton h-14 rounded-xl" />)}</div>;
}
function Empty({ title, detail }: { title: string; detail: string }) {
  return <div className="rounded-2xl border border-dashed border-border bg-background/50 p-10 text-center" data-testid="state-empty"><PackageCheck className="mx-auto mb-3 size-7 text-primary" /><p className="font-semibold">{title}</p><p className="mt-1 text-sm text-muted-foreground">{detail}</p></div>;
}
function ErrorState({ onRetry }: { onRetry: () => void }) {
  return <div className="rounded-2xl border border-destructive/30 bg-destructive/5 p-8 text-center" data-testid="state-error"><AlertTriangle className="mx-auto mb-2 size-6 text-destructive" /><p className="font-semibold">The command feed is unavailable</p><button data-testid="button-retry" onClick={onRetry} className="mt-4 rounded-lg bg-primary px-4 py-2 text-sm font-semibold text-primary-foreground">Retry connection</button></div>;
}
function Tag({ children, kind = 'muted' }: { children: React.ReactNode; kind?: string }) {
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-[.12em] ${kind === 'good' ? 'bg-primary/10 text-primary' : kind === 'warn' ? 'bg-accent/20 text-foreground' : kind === 'danger' ? 'bg-destructive/10 text-destructive' : 'bg-muted text-muted-foreground'}`}>{children}</span>;
}
function Button({ children, onClick, type = 'button', variant = 'primary', disabled = false, testId }: { children: React.ReactNode; onClick?: () => void; type?: 'button' | 'submit'; variant?: 'primary' | 'outline' | 'quiet' | 'danger'; disabled?: boolean; testId: string }) {
  return <button data-testid={testId} type={type} onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-xl px-3.5 py-2.5 text-sm font-semibold disabled:cursor-not-allowed disabled:opacity-50 ${variant === 'primary' ? 'bg-primary text-primary-foreground hover:opacity-90' : variant === 'danger' ? 'border border-destructive/25 bg-destructive/8 text-destructive hover:bg-destructive/15' : variant === 'outline' ? 'border border-border bg-card text-foreground hover:border-primary/50 hover:bg-muted' : 'text-muted-foreground hover:bg-muted hover:text-foreground'}`}>{children}</button>;
}
function Metric({ label, value, suffix, trend, accent = 'primary' }: { label: string; value: string | number; suffix?: string; trend?: string; accent?: string }) {
  return <div className="panel panel-hover p-5" data-testid={`metric-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-start justify-between"><span className="eyebrow">{label}</span><span className={`size-2 rounded-full ${accent === 'accent' ? 'bg-accent' : accent === 'danger' ? 'bg-destructive' : 'bg-primary'}`} /></div><div className="mt-3 flex items-baseline gap-1"><span className="display text-3xl font-semibold">{value}</span>{suffix && <span className="text-sm text-muted-foreground">{suffix}</span>}</div>{trend && <div className="mt-2 flex items-center gap-1 text-xs font-semibold text-primary"><ArrowUpRight className="size-3.5" />{trend}</div>}</div>;
}
function SectionHeader({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail?: string; action?: React.ReactNode }) {
  return <div className="mb-5 flex flex-wrap items-end justify-between gap-3"><div><div className="eyebrow">{eyebrow}</div><h2 className="display mt-1 text-2xl font-semibold tracking-tight">{title}</h2>{detail && <p className="mt-1 text-sm text-muted-foreground">{detail}</p>}</div>{action}</div>;
}

function Shell({ children }: { children: React.ReactNode }) {
  const [location, setLocation] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const alertsQ = useGetAlerts({ query: { queryKey: getGetAlertsQueryKey() } });
  const active = nav.find((item) => item.href === location)?.label ?? 'Command center';
  const unreadAlerts = alertsQ.data?.filter((alert) => alert.status === 'unread') ?? [];
  return <div className="app-shell flex">
    <aside className={`fixed inset-y-0 left-0 z-40 w-[270px] shrink-0 border-r border-sidebar-border bg-sidebar text-sidebar-foreground transition-transform lg:static lg:translate-x-0 ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="flex h-full flex-col px-4 py-5">
        <div className="flex items-center justify-between px-3"><Link href="/" data-testid="link-brand" className="flex items-center gap-3"><span className="grid size-9 place-items-center rounded-xl bg-sidebar-primary text-sidebar-primary-foreground"><Leaf className="size-5" /></span><span><span className="block font-semibold tracking-tight">NourishLoop</span><span className="block text-[10px] uppercase tracking-[.18em] text-sidebar-foreground/55">AI command center</span></span></Link><button data-testid="button-close-menu" onClick={() => setMobileOpen(false)} className="rounded-lg p-2 text-sidebar-foreground/60 hover:bg-sidebar-accent lg:hidden"><X className="size-4" /></button></div>
        <div className="mt-9 px-3"><div className="eyebrow !text-sidebar-foreground/45">Riverside campus</div><div className="mt-1 flex items-center gap-2 text-xs text-sidebar-foreground/70"><CircleDot className="size-3 fill-sidebar-primary text-sidebar-primary" /> Live operations <span className="ml-auto mono text-[10px]">06:42 IST</span></div></div>
        <nav className="mt-7 flex-1 space-y-1">{nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setMobileOpen(false)} className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm ${location === href ? 'bg-sidebar-accent text-sidebar-accent-foreground' : 'text-sidebar-foreground/65 hover:bg-sidebar-accent/65 hover:text-sidebar-foreground'}`}><Icon className={`size-4 ${location === href ? 'text-sidebar-primary' : ''}`} /><span>{label}</span>{label === 'Alerts' && <span className="ml-auto rounded-full bg-accent px-2 py-0.5 text-[10px] font-bold text-accent-foreground">3</span>}</Link>)}</nav>
        <div className="rounded-2xl border border-sidebar-border bg-sidebar-accent/55 p-3.5"><div className="flex items-center justify-between"><span className="eyebrow !text-sidebar-foreground/45">Today’s loop</span><Sparkles className="size-4 text-sidebar-primary" /></div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-sidebar-foreground/10"><div className="h-full w-[72%] rounded-full bg-sidebar-primary" /></div><div className="mt-2 flex justify-between text-xs text-sidebar-foreground/65"><span>72% on track</span><span className="mono">14:18 left</span></div></div>
         <div className="mt-4 border-t border-sidebar-border pt-4"><div className="flex items-center gap-3 px-2"><div className="grid size-8 place-items-center rounded-full bg-sidebar-primary/15 text-xs font-bold text-sidebar-primary">KL</div><div><div className="text-sm font-semibold">Kitchen lead</div><div className="text-[11px] text-sidebar-foreground/50">Riverside campus</div></div><button data-testid="button-profile" onClick={() => setLocation('/settings')} className="ml-auto rounded-lg p-1.5 text-sidebar-foreground/50 hover:bg-sidebar-accent" aria-label="Open settings"><SlidersHorizontal className="size-4" /></button></div></div>
      </div>
    </aside>
    {mobileOpen && <button data-testid="button-overlay" className="fixed inset-0 z-30 bg-foreground/30 lg:hidden" onClick={() => setMobileOpen(false)} aria-label="Close navigation" />}
     <main className="min-w-0 flex-1"><header className="sticky top-0 z-20 border-b border-border bg-background/90 backdrop-blur-md"><div className="content-wrap flex h-[72px] items-center justify-between gap-4 px-5 md:px-8"><div className="flex items-center gap-3"><button data-testid="button-open-menu" onClick={() => setMobileOpen(true)} className="rounded-xl border border-border bg-card p-2.5 lg:hidden"><Menu className="size-4" /></button><div><div className="eyebrow">Operations / {active}</div><div className="mt-1 flex items-center gap-2 text-sm font-semibold"><CloudSun className="size-4 text-accent-foreground" /> {currentDateLabel()} <span className="hidden text-muted-foreground sm:inline">·</span><span className="hidden text-xs font-normal text-muted-foreground sm:inline">Service window closes 21:30</span></div></div></div><div className="relative flex items-center gap-2"><div className="hidden items-center gap-2 rounded-full border border-border bg-card px-3 py-2 text-xs text-muted-foreground md:flex"><CircleDot className="size-3 fill-primary text-primary" /> API synced 2 min ago</div><button data-testid="button-header-alerts" onClick={() => setNotificationsOpen((open) => !open)} aria-label="Open notifications" aria-expanded={notificationsOpen} className="relative rounded-xl border border-border bg-card p-2.5 hover:bg-muted"><Bell className="size-4" />{unreadAlerts.length > 0 && <span className="absolute -right-1 -top-1 grid min-h-4 min-w-4 place-items-center rounded-full border-2 border-background bg-accent px-1 text-[9px] font-bold text-accent-foreground">{unreadAlerts.length}</span>}</button>{notificationsOpen && <div data-testid="notification-panel" className="absolute right-0 top-12 z-30 w-[min(360px,calc(100vw-2rem))] rounded-2xl border border-border bg-card p-3 shadow-xl"><div className="flex items-center justify-between px-2 py-1"><div><div className="eyebrow">Notifications</div><div className="mt-1 text-sm font-semibold">{unreadAlerts.length ? `${unreadAlerts.length} need attention` : 'You are all caught up'}</div></div><Bell className="size-4 text-primary" /></div><div className="mt-3 max-h-72 space-y-2 overflow-auto">{alertsQ.isLoading ? <Loading lines={2} /> : unreadAlerts.length ? unreadAlerts.slice(0, 4).map((alert) => <button key={alert.id} data-testid={`notification-${alert.id}`} onClick={() => { setNotificationsOpen(false); setLocation('/alerts'); }} className="w-full rounded-xl border border-border p-3 text-left hover:border-primary/40 hover:bg-primary/[.03]"><div className="flex items-start gap-2"><span className={`mt-1 size-2 shrink-0 rounded-full ${tone(alert.severity) === 'danger' ? 'bg-destructive' : tone(alert.severity) === 'warn' ? 'bg-accent' : 'bg-primary'}`} /><span><span className="block text-sm font-semibold">{alert.title}</span><span className="mt-1 block text-xs leading-5 text-muted-foreground">{alert.description}</span></span></div></button>) : <div className="rounded-xl bg-secondary/50 p-4 text-center text-xs text-muted-foreground">No unread notifications.</div>}</div><button data-testid="button-see-all-notifications" onClick={() => { setNotificationsOpen(false); setLocation('/alerts'); }} className="mt-3 w-full rounded-xl bg-secondary px-3 py-2.5 text-xs font-semibold text-foreground hover:bg-primary/10 hover:text-primary">See all alerts</button></div>}</div></div></header><div className="content-wrap px-5 py-7 md:px-8 md:py-9">{children}</div></main>
  </div>;
}

function OverviewPage() {
  const q = useGetOverview({ query: { queryKey: getGetOverviewQueryKey() } });
  const activityQ = useGetActivity({ query: { queryKey: getGetActivityQueryKey() } });
  const [, setLocation] = useLocation();
  const overview = q.data;
  const metrics = overview?.metrics ?? {};
  const recommendationRoutes: Record<string, string> = { 'rec-1': '/forecast', 'rec-2': '/surplus', 'rec-3': '/inventory' };
  return <PageFrame title={greeting()} detail="A clear read on today’s kitchen-to-community loop." action={<Link href="/forecast" data-testid="link-overview-forecast" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground hover:opacity-90">Review today’s production <ChevronRight className="size-4" /></Link>}>
    {q.isLoading ? <Loading lines={3} /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Meals in motion" value={compact(metrics.mealsRedistributed ?? metrics.meals_in_motion ?? 1248)} suffix="meals" trend="+12.4% vs last Wed" /><Metric label="Waste avoided" value={metrics.wasteAvoidedKg ?? metrics.waste_avoided_kg ?? 186} suffix="kg" trend="14.8 kg more than plan" accent="accent" /><Metric label="Today’s risk" value={metrics.riskScore ?? metrics.risk_score ?? 'Low'} trend="2 actions before 11:00" accent="danger" /><Metric label="Loop efficiency" value={metrics.successRate ?? metrics.success_rate ?? 91} suffix="%" trend="+3.2 pts this week" /></div><div className="mt-7 grid gap-5 xl:grid-cols-[1.45fr_.8fr]"><div className="panel p-5 md:p-6"><SectionHeader eyebrow="Production signal" title="Plan against reality" detail="The last seven service windows, meals prepared versus served." action={<Tag kind="good">Healthy loop</Tag>} /><div className="chart-grid relative h-56 overflow-hidden rounded-xl border border-border p-4"><div className="absolute inset-x-4 bottom-8 top-6 flex items-end justify-between gap-2">{(overview?.trends ?? []).slice(-7).map((point, i) => <div key={`${point.label}-${i}`} className="flex h-full flex-1 items-end justify-center gap-1"><div className="w-2.5 rounded-t-full bg-primary/30" style={{ height: `${Math.max(12, Math.min(92, (point.planned / Math.max(point.actual, point.planned, 1)) * 75))}%` }} /><div className="w-2.5 rounded-t-full bg-primary" style={{ height: `${Math.max(9, Math.min(88, (point.actual / Math.max(point.planned, point.actual, 1)) * 78))}%` }} /></div>)}{!(overview?.trends?.length) && <div className="absolute inset-0 grid place-items-center text-sm text-muted-foreground">Awaiting enough service windows for a trend.</div>}<div className="absolute inset-x-4 bottom-2 flex justify-between text-[10px] text-muted-foreground">{(overview?.trends ?? []).slice(-7).map((point, i) => <span key={`${point.label}-label-${i}`}>{point.label}</span>)}</div></div><div className="mt-3 flex items-center gap-4 text-xs text-muted-foreground"><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-primary/30" /> Planned</span><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-primary" /> Served</span></div></div><div className="panel p-5 md:p-6"><SectionHeader eyebrow="Human impact" title="Recommended next moves" /><div className="space-y-4">{(overview?.recommendations ?? []).slice(0, 3).map((r) => <div key={r.id} className="border-b border-border pb-4 last:border-0 last:pb-0"><div className="flex items-start justify-between gap-3"><div><div className="text-sm font-semibold">{r.title}</div><p className="mt-1 text-xs leading-5 text-muted-foreground">{r.description}</p></div><Tag kind={tone(r.priority)}>{r.priority}</Tag></div><div className="mt-3 flex items-center justify-between"><span className="text-xs font-medium text-primary">{r.impact}</span><button data-testid={`button-recommendation-${r.id}`} onClick={() => setLocation(recommendationRoutes[r.id] ?? '/alerts')} className="text-xs font-semibold text-foreground hover:text-primary">{r.actionLabel ?? 'Open action'} <ChevronRight className="inline size-3" /></button></div></div>)}{!(overview?.recommendations?.length) && <Empty title="The loop is quiet" detail="No recommendations need your attention right now." />}</div></div></div><div className="mt-5 grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><div className="panel p-5"><SectionHeader eyebrow="Attention" title="Operational alerts" action={<Link href="/alerts" data-testid="link-overview-alerts" className="text-xs font-bold text-primary">See all <ChevronRight className="inline size-3" /></Link>} /><div className="space-y-2">{(overview?.alerts ?? []).slice(0, 4).map((a) => <AlertRow key={a.id} alert={a} />)}{!(overview?.alerts?.length) && <Empty title="No active alerts" detail="Your operating rhythm is clear." />}</div></div><div className="panel p-5"><SectionHeader eyebrow="Live feed" title="Activity across the loop" /><div className="space-y-1">{(activityQ.data ?? []).slice(0, 5).map((event) => <div key={event.id} className="flex gap-3 border-b border-border py-3 last:border-0"><div className="mt-1.5 size-2 shrink-0 rounded-full bg-primary" /><div className="min-w-0 flex-1"><div className="text-sm font-medium">{event.title}</div><p className="truncate text-xs text-muted-foreground">{event.description}</p></div><span className="mono shrink-0 text-[10px] text-muted-foreground">{event.time}</span></div>)}</div></div></div></div></>}
  </PageFrame>;
}
function AlertRow({ alert, onResolve }: { alert: any; onResolve?: () => void }) {
  return <div className="flex items-start gap-3 rounded-xl border border-border bg-background/55 p-3.5" data-testid={`alert-row-${alert.id}`}><span className={`mt-0.5 grid size-7 place-items-center rounded-lg ${tone(alert.severity) === 'danger' ? 'bg-destructive/10 text-destructive' : 'bg-accent/20 text-foreground'}`}><AlertTriangle className="size-3.5" /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="text-sm font-semibold">{alert.title}</span><Tag kind={tone(alert.severity)}>{alert.severity}</Tag></div><p className="mt-1 text-xs leading-5 text-muted-foreground">{alert.description}</p></div>{onResolve && <button data-testid={`button-resolve-alert-${alert.id}`} onClick={onResolve} className="rounded-lg p-1.5 text-muted-foreground hover:bg-muted hover:text-primary"><Check className="size-4" /></button>}</div>;
}
function PageFrame({ title, detail, action, children }: { title: string; detail: string; action?: React.ReactNode; children: React.ReactNode }) {
  return <div className="animate-rise"><div className="mb-8 flex flex-wrap items-end justify-between gap-4"><div><div className="eyebrow">NourishLoop / Riverside campus</div><h1 className="display mt-2 text-4xl font-semibold leading-[1.05] md:text-5xl">{title}</h1><p className="mt-3 max-w-2xl text-sm text-muted-foreground">{detail}</p></div>{action}</div>{children}</div>;
}

function ForecastPage() {
  const q = useGetForecasts(undefined, { query: { queryKey: getGetForecastsQueryKey() } });
  const mutation = useGenerateForecast();
  const [attendance, setAttendance] = useState('1200');
  const [date, setDate] = useState('2024-06-13');
  const [showForm, setShowForm] = useState(false);
  const generate = (e: React.FormEvent) => { e.preventDefault(); mutation.mutate({ data: { forecastDate: date, attendance: Number(attendance) } }, { onSuccess: () => { setShowForm(false); queryClient.invalidateQueries({ queryKey: getGetForecastsQueryKey() }); } }); };
  return <PageFrame title="Demand, made legible." detail="See the likely service load before the first prep begins. Every range is a decision boundary, not a guess." action={<Button testId="button-open-forecast-form" onClick={() => setShowForm((v) => !v)}><Sparkles className="size-4" /> Generate revision</Button>}>
    {showForm && <form onSubmit={generate} className="panel mb-5 grid gap-4 border-primary/30 bg-primary/[.035] p-5 md:grid-cols-[1fr_1fr_auto] md:items-end" data-testid="form-generate-forecast"><label className="text-xs font-semibold">Service date<input data-testid="input-forecast-date" type="date" value={date} onChange={(e) => setDate(e.target.value)} className="mt-2 block w-full rounded-xl border border-input bg-card px-3 py-2.5 text-sm" /></label><label className="text-xs font-semibold">Expected attendance<input data-testid="input-forecast-attendance" type="number" min="1" value={attendance} onChange={(e) => setAttendance(e.target.value)} className="mt-2 block w-full rounded-xl border border-input bg-card px-3 py-2.5 text-sm" /></label><Button type="submit" testId="button-submit-forecast" disabled={mutation.isPending}>{mutation.isPending ? 'Recalculating…' : 'Calculate range'}</Button></form>}
    {q.isLoading ? <Loading lines={5} /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : <div className="space-y-3">{(q.data ?? []).map((f) => <div className="panel panel-hover grid gap-4 p-5 md:grid-cols-[1.1fr_1fr_1fr_auto] md:items-center" key={f.id} data-testid={`forecast-card-${f.id}`}><div><div className="eyebrow">{day(f.forecastDate)} / {f.mealType}</div><div className="mt-1 text-lg font-semibold">{money(f.recommendedProduction)} meals to prep</div><p className="mt-1 text-xs text-muted-foreground">{f.explanation}</p></div><div><div className="flex justify-between text-xs text-muted-foreground"><span>Demand range</span><span className="mono">{f.lowerBound}–{f.upperBound}</span></div><div className="mt-2 h-2 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${Math.min(100, f.confidence)}%` }} /></div><div className="mt-1 text-[10px] text-muted-foreground">{f.confidence}% confidence</div></div><div className="rounded-xl bg-secondary/55 p-3"><div className="eyebrow">Signal</div><div className="mt-1 text-sm font-semibold">{f.predictedMeals} likely covers service</div></div><Tag kind={f.confidence > 85 ? 'good' : 'warn'}>{f.confidence > 85 ? 'High confidence' : 'Watch range'}</Tag></div>)}{!(q.data?.length) && <Empty title="No forecasts in view" detail="Generate a service-day forecast to put the first range on the board." />}</div>}
  </PageFrame>;
}

function InventoryPage() {
  const [search, setSearch] = useState('');
  const q = useGetInventory({ search }, { query: { queryKey: getGetInventoryQueryKey({ search }) } });
  const zonesQ = useGetStorageZones({ query: { queryKey: getGetStorageZonesQueryKey() } });
  const create = useCreateInventory();
  const update = useUpdateInventory();
  const scan = useScanInventoryQuality();
  const simulate = useSimulateStorageUpdate();
  const [formOpen, setFormOpen] = useState(false);
  const [form, setForm] = useState({ name: '', quantity: '20', unit: 'kg', expiresAt: '2024-06-14T12:00' });
  const [scanResult, setScanResult] = useState<any>(null);
  const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: { ...form, quantity: Number(form.quantity) } }, { onSuccess: () => { setFormOpen(false); setForm({ name: '', quantity: '20', unit: 'kg', expiresAt: '2024-06-14T12:00' }); queryClient.invalidateQueries({ queryKey: getGetInventoryQueryKey({ search }) }); } }); };
  return <PageFrame title="Know what needs care." detail="Freshness is an operational variable. Surface the items that need a decision before they become waste." action={<Button testId="button-open-inventory-form" onClick={() => setFormOpen((v) => !v)}><PackageCheck className="size-4" /> Add stock</Button>}>
    {formOpen && <form onSubmit={submit} className="panel mb-5 grid gap-3 border-primary/30 bg-primary/[.035] p-5 md:grid-cols-4" data-testid="form-create-inventory"><input data-testid="input-inventory-name" required placeholder="Ingredient name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="rounded-xl border border-input bg-card px-3 py-2.5 text-sm" /><input data-testid="input-inventory-quantity" required type="number" placeholder="Quantity" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })} className="rounded-xl border border-input bg-card px-3 py-2.5 text-sm" /><input data-testid="input-inventory-expiry" required type="datetime-local" value={form.expiresAt} onChange={(e) => setForm({ ...form, expiresAt: e.target.value })} className="rounded-xl border border-input bg-card px-3 py-2.5 text-sm" /><Button type="submit" testId="button-submit-inventory" disabled={create.isPending}>{create.isPending ? 'Adding…' : 'Add to inventory'}</Button></form>}
    <div className="mb-5 flex flex-wrap items-center gap-3"><div className="relative flex-1 md:max-w-sm"><ScanLine className="absolute left-3 top-3 size-4 text-muted-foreground" /><input data-testid="input-inventory-search" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search ingredients" className="w-full rounded-xl border border-input bg-card py-2.5 pl-9 pr-3 text-sm outline-none focus:border-primary" /></div><div className="flex items-center gap-2 text-xs text-muted-foreground"><Thermometer className="size-4 text-primary" /> {zonesQ.data?.length ?? 0} storage zones reporting</div></div>
    {scanResult && <div className="panel mb-5 border-primary/30 bg-primary/[.035] p-5" data-testid="quality-scan-result"><div className="flex justify-between"><div><div className="eyebrow">Quality assessment</div><div className="mt-1 text-lg font-semibold">{scanResult.recommendation}</div></div><Tag kind={tone(String(scanResult.risk)) === 'danger' ? 'danger' : 'good'}>{scanResult.freshness}% fresh</Tag></div><div className="mt-3 flex flex-wrap gap-2">{(scanResult.indicators ?? []).map((x: string) => <Tag key={x}>{x}</Tag>)}</div></div>}
    {q.isLoading ? <Loading lines={5} /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : <div className="panel overflow-hidden"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><div className="eyebrow">Live stock ledger</div><div className="mt-1 text-sm font-semibold">{q.data?.length ?? 0} items in the active window</div></div><Tag kind="good">Sensor sync on</Tag></div><div className="divide-y divide-border">{(q.data ?? []).map((item) => <div key={item.id} className="grid gap-3 px-5 py-4 md:grid-cols-[1.5fr_.8fr_.8fr_.8fr_auto] md:items-center" data-testid={`inventory-row-${item.id}`}><div><div className="font-semibold">{item.name}</div><div className="mt-1 text-xs text-muted-foreground">{item.category} · {item.storageZone} {item.batch && `· ${item.batch}`}</div></div><div><div className="text-sm font-semibold">{item.quantity} {item.unit}</div><div className="text-xs text-muted-foreground">{item.servings} portions</div></div><div><div className="text-xs text-muted-foreground">Expires</div><div className="mt-1 text-sm font-semibold">{day(item.expiresAt)}</div></div><div><Tag kind={tone(item.status) === 'danger' || item.risk > 70 ? 'danger' : item.risk > 40 ? 'warn' : 'good'}>{item.status || `${item.risk}% risk`}</Tag><div className="mt-1 text-[10px] text-muted-foreground">{item.temperature}°C · {item.freshness}% fresh</div></div><div className="flex justify-end gap-1"><button data-testid={`button-scan-${item.id}`} onClick={() => scan.mutate({ id: item.id }, { onSuccess: setScanResult })} className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-primary" title="Scan quality"><ScanLine className="size-4" /></button><button data-testid={`button-use-${item.id}`} onClick={() => update.mutate({ id: item.id, data: { status: 'allocated' } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetInventoryQueryKey({ search }) }) })} className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-primary" title="Allocate stock"><Check className="size-4" /></button></div></div>)}{!(q.data?.length) && <div className="p-8"><Empty title="No stock matches" detail="Try another ingredient or add a fresh item to the ledger." /></div>}</div></div>}
    {!!zonesQ.data?.length && <div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{zonesQ.data.map((z) => <div key={z.id} className="panel p-4" data-testid={`storage-zone-${z.id}`}><div className="flex items-center justify-between"><span className="text-sm font-semibold">{z.name}</span><button data-testid={`button-simulate-zone-${z.id}`} onClick={() => simulate.mutate({ id: z.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetStorageZonesQueryKey() }) })} className="text-muted-foreground hover:text-primary"><RefreshCw className={`size-3.5 ${simulate.isPending ? 'animate-spin' : ''}`} /></button></div><div className="mt-3 flex items-end justify-between"><div className="display text-2xl font-semibold">{z.temperature}°<span className="font-sans text-xs">C</span></div><Tag kind={tone(z.status)}>{z.status}</Tag></div><div className="mt-2 text-xs text-muted-foreground">{z.humidity}% humidity</div></div>)}</div>}
  </PageFrame>;
}

function SurplusPage() {
  const q = useGetSurplus(undefined, { query: { queryKey: getGetSurplusQueryKey() } });
  const [selected, setSelected] = useState('');
  const visibleBatches = (q.data ?? []).filter((batch) => !['cancelled', 'expired'].includes(batch.status));
  const selectedId = selected && visibleBatches.some((batch) => batch.id === selected) ? selected : visibleBatches[0]?.id ?? '';
  const matchesQ = useGetSurplusMatches(selectedId, { query: { enabled: !!selectedId, queryKey: getGetSurplusMatchesQueryKey(selectedId) } });
  const partnersQ = useGetPartners({ query: { queryKey: getGetPartnersQueryKey() } });
  const create = useCreateSurplus();
  const update = useUpdateSurplus();
  const accept = useAcceptSurplusMatch();
  const [formOpen, setFormOpen] = useState(false);
  const [form, setForm] = useState({ foodName: '', servings: '80', bestBefore: '2024-06-12T18:00', dietaryTags: '' });
  const submit = (e: React.FormEvent) => { e.preventDefault(); create.mutate({ data: { foodName: form.foodName, servings: Number(form.servings), bestBefore: form.bestBefore, dietaryTags: form.dietaryTags.split(',').map((x) => x.trim()).filter(Boolean) } }, { onSuccess: () => { setFormOpen(false); queryClient.invalidateQueries({ queryKey: getGetSurplusQueryKey() }); } }); };
  return <PageFrame title="Keep good food moving." detail="Match surplus to trusted local capacity while the quality window is still open." action={<Button testId="button-open-surplus-form" onClick={() => setFormOpen((v) => !v)}><GitBranch className="size-4" /> List surplus</Button>}>
    {formOpen && <form onSubmit={submit} className="panel mb-5 grid gap-3 border-primary/30 bg-primary/[.035] p-5 md:grid-cols-4" data-testid="form-create-surplus"><input data-testid="input-surplus-food" required placeholder="Prepared food" value={form.foodName} onChange={(e) => setForm({ ...form, foodName: e.target.value })} className="rounded-xl border border-input bg-card px-3 py-2.5 text-sm" /><input data-testid="input-surplus-servings" required type="number" value={form.servings} onChange={(e) => setForm({ ...form, servings: e.target.value })} className="rounded-xl border border-input bg-card px-3 py-2.5 text-sm" /><input data-testid="input-surplus-best-before" required type="datetime-local" value={form.bestBefore} onChange={(e) => setForm({ ...form, bestBefore: e.target.value })} className="rounded-xl border border-input bg-card px-3 py-2.5 text-sm" /><Button type="submit" testId="button-submit-surplus" disabled={create.isPending}>{create.isPending ? 'Listing…' : 'Publish to network'}</Button></form>}
    <div className="mb-5 flex items-center justify-between"><div className="text-sm text-muted-foreground"><span className="font-semibold text-foreground">{q.data?.length ?? 0}</span> batches in the exchange</div><div className="flex items-center gap-2 text-xs text-muted-foreground"><Users className="size-4 text-primary" /> {partnersQ.data?.length ?? 0} trusted partners</div></div>
     {q.isLoading ? <Loading lines={4} /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : <div className="grid gap-4 xl:grid-cols-[1.15fr_.85fr]"><div className="space-y-3"><div className="text-sm text-muted-foreground"><span className="font-semibold text-foreground">{visibleBatches.length}</span> active batches in the exchange</div>{visibleBatches.map((batch) => <div key={batch.id} onClick={() => setSelected(batch.id)} className={`panel panel-hover cursor-pointer p-5 ${batch.id === selectedId ? 'border-primary/50 ring-1 ring-primary/15' : ''}`} data-testid={`surplus-card-${batch.id}`}><div className="flex items-start justify-between gap-3"><div><div className="eyebrow">{batch.location} · {day(batch.preparedAt)}</div><div className="mt-1 text-lg font-semibold">{batch.foodName}</div></div><Tag kind={batch.qualityStatus === 'approved' || batch.qualityStatus === 'safe' ? 'good' : 'warn'}>{batch.qualityStatus}</Tag></div><div className="mt-5 grid grid-cols-3 gap-3 border-y border-border py-3"><div><div className="eyebrow">Servings</div><div className="mt-1 font-semibold">{batch.servings}</div></div><div><div className="eyebrow">Best before</div><div className="mt-1 font-semibold">{time(batch.bestBefore)}</div></div><div><div className="eyebrow">Value</div><div className="mt-1 font-semibold">₹{money(batch.valueInr)}</div></div></div><div className="mt-4 flex flex-wrap gap-2">{batch.dietaryTags?.map((tag) => <Tag key={tag}>{tag}</Tag>)}</div><div className="mt-4 flex items-center gap-2"><div className="h-1.5 flex-1 rounded-full bg-muted"><div className="h-full rounded-full bg-primary" style={{ width: `${batch.progress ?? 45}%` }} /></div><span className="mono text-[10px] text-muted-foreground">{batch.progress ?? 45}% matched</span><button data-testid={`button-archive-surplus-${batch.id}`} onClick={(event) => { event.stopPropagation(); update.mutate({ id: batch.id, data: { status: 'cancelled' } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetSurplusQueryKey() }) }); }} className="ml-2 rounded-lg p-1.5 text-muted-foreground hover:bg-muted" aria-label={`Archive ${batch.foodName}`}><X className="size-4" /></button></div></div>)}{!visibleBatches.length && <Empty title="No surplus is listed" detail="Publish the next safe-to-share batch and matching can begin." />}</div><div className="panel p-5"><SectionHeader eyebrow="Recommended match" title={selectedId ? `Best homes for ${visibleBatches.find((batch) => batch.id === selectedId)?.foodName ?? 'this batch'}` : 'Matching intelligence'} detail="Ranking balances distance, capacity, reliability and the live quality window." />{matchesQ.isLoading ? <Loading lines={3} /> : (matchesQ.data ?? []).length ? <div className="space-y-3">{(matchesQ.data ?? []).map((match) => <div key={match.id} className="rounded-xl border border-border p-4" data-testid={`match-card-${match.id}`}><div className="flex items-start justify-between gap-2"><div><div className="font-semibold">{match.partnerName}</div><div className="mt-1 text-xs text-muted-foreground">{match.distanceKm} km · pickup in {match.pickupMinutes} min</div></div><div className="text-right"><div className="display text-2xl font-semibold text-primary">{match.score}</div><div className="eyebrow">fit score</div></div></div><p className="mt-3 text-xs leading-5 text-muted-foreground">{match.reason}</p><Button testId={`button-accept-match-${match.id}`} onClick={() => accept.mutate({ id: selectedId, matchId: match.id }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetSurplusQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetSurplusMatchesQueryKey(selectedId) }); } })} disabled={accept.isPending} variant={match.status === 'accepted' ? 'outline' : 'primary'}>{match.status === 'accepted' ? 'Accepted' : 'Accept match'}</Button></div>)}</div> : <Empty title="Select a live batch" detail="Matching will appear when a publishable batch is selected." />}</div></div>}
  </PageFrame>;
}

function LogisticsPage() {
  const q = useGetRoutes({ query: { queryKey: getGetRoutesQueryKey() } });
  const surplusQ = useGetSurplus(undefined, { query: { queryKey: getGetSurplusQueryKey() } });
  const partnersQ = useGetPartners({ query: { queryKey: getGetPartnersQueryKey() } });
  const optimize = useOptimizeRoute();
  const [surplusId, setSurplusId] = useState('');
  const [partnerId, setPartnerId] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); optimize.mutate({ data: { surplusId, partnerId } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetRoutesQueryKey() }) }); };
  return <PageFrame title="Make every pickup count." detail="Routes are shaped around the quality window: fewer kilometres, more certainty, more meals delivered." action={<Button testId="button-refresh-routes" onClick={() => q.refetch()} variant="outline"><RefreshCw className="size-4" /> Refresh routes</Button>}>
    <form onSubmit={submit} className="panel mb-5 grid gap-3 border-primary/30 bg-primary/[.035] p-5 md:grid-cols-[1fr_1fr_auto] md:items-end" data-testid="form-optimize-route"><label className="text-xs font-semibold">Surplus batch<select data-testid="select-route-surplus" required value={surplusId} onChange={(e) => setSurplusId(e.target.value)} className="mt-2 block w-full rounded-xl border border-input bg-card px-3 py-2.5 text-sm"><option value="">Choose a batch</option>{(surplusQ.data ?? []).map((x) => <option key={x.id} value={x.id}>{x.foodName} · {x.servings} servings</option>)}</select></label><label className="text-xs font-semibold">Partner<select data-testid="select-route-partner" required value={partnerId} onChange={(e) => setPartnerId(e.target.value)} className="mt-2 block w-full rounded-xl border border-input bg-card px-3 py-2.5 text-sm"><option value="">Choose a partner</option>{(partnersQ.data ?? []).map((x) => <option key={x.id} value={x.id}>{x.name}</option>)}</select></label><Button type="submit" testId="button-optimize-route" disabled={optimize.isPending}>{optimize.isPending ? 'Finding route…' : 'Optimize pickup'}</Button></form>
    {q.isLoading ? <Loading lines={3} /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : <div className="grid gap-4 md:grid-cols-2">{(q.data ?? []).map((route) => <div className="panel panel-hover p-5" key={route.id} data-testid={`route-card-${route.id}`}><div className="flex items-start justify-between"><div><div className="eyebrow">{route.title}</div><div className="mt-1 flex items-center gap-2 text-lg font-semibold"><RouteIcon className="size-5 text-primary" /> {route.distanceKm} km loop</div></div><Tag kind={tone(route.status)}>{route.status}</Tag></div><div className="mt-5 grid grid-cols-3 gap-3"><div><div className="eyebrow">Duration</div><div className="mt-1 font-semibold">{route.durationMinutes} min</div></div><div><div className="eyebrow">Emissions</div><div className="mt-1 font-semibold">{route.emissionsKg} kg CO₂e</div></div><div><div className="eyebrow">Stops</div><div className="mt-1 font-semibold">{route.stops?.length ?? 0}</div></div></div><div className="mt-5 space-y-2">{(route.stops ?? []).map((stop, i) => <div key={`${stop.name}-${i}`} className="flex items-center gap-3 text-sm"><span className="grid size-6 place-items-center rounded-full bg-secondary text-[10px] font-bold">{i + 1}</span><span className="flex-1">{stop.name}</span><span className="mono text-[10px] text-muted-foreground">{stop.eta}</span></div>)}</div></div>)}{!(q.data?.length) && <div className="md:col-span-2"><Empty title="No routes in motion" detail="Optimize the first pickup above to create a route." /></div>}</div>}
  </PageFrame>;
}

function OperationsPage() {
  const activityQ = useGetActivity({ query: { queryKey: getGetActivityQueryKey() } });
  const inventoryQ = useGetInventory(undefined, { query: { queryKey: getGetInventoryQueryKey() } });
  const [line, setLine] = useState('Line A');
  const inPrep = inventoryQ.data?.filter((item) => item.status?.toLowerCase().includes('prep') || item.status?.toLowerCase().includes('allocated')).length ?? 0;
  return <PageFrame title="The kitchen, in rhythm." detail="A single operating view for prep, handoff and the small decisions that keep service moving."><div className="grid gap-4 sm:grid-cols-3"><Metric label="Active lines" value="3" suffix="of 4" trend="All critical paths covered" /><Metric label="Prep allocated" value={inPrep || 18} suffix="batches" trend="82% before handoff" accent="accent" /><Metric label="Next handoff" value="11:45" suffix="IST" trend="Partner briefed" /></div><div className="mt-7 grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><div className="panel p-5"><SectionHeader eyebrow="Processing lines" title="Today’s production floor" detail="Update the active line to keep the handoff ledger honest." action={<select data-testid="select-operations-line" value={line} onChange={(e) => setLine(e.target.value)} className="rounded-lg border border-input bg-card px-3 py-2 text-xs"><option>Line A</option><option>Line B</option><option>Cold prep</option></select>} /><div className="space-y-4">{['Receiving & sort', 'Prep & portion', 'Pack & label', 'Handoff staging'].map((label, i) => <div key={label} className="flex items-center gap-4"><div className={`grid size-9 place-items-center rounded-xl ${i < 2 ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>{i < 2 ? <Check className="size-4" /> : <span className="mono text-xs">{i + 1}</span>}</div><div className="min-w-0 flex-1"><div className="flex justify-between text-sm font-semibold"><span>{label}</span><span className="mono text-[10px] text-muted-foreground">{i < 2 ? 'complete' : i === 2 ? 'in progress' : 'queued'}</span></div><div className="mt-2 h-2 rounded-full bg-muted"><div className={`h-full rounded-full ${i < 2 ? 'w-full bg-primary' : i === 2 ? 'w-[58%] bg-accent' : 'w-[12%] bg-muted-foreground/30'}`} /></div></div></div>)}</div></div><div className="panel p-5"><SectionHeader eyebrow="Floor feed" title="Recent handoffs" /><div className="space-y-3">{(activityQ.data ?? []).slice(0, 6).map((e) => <div key={e.id} className="flex gap-3"><div className="mt-1 size-2 shrink-0 rounded-full bg-primary" /><div><div className="text-sm font-semibold">{e.title}</div><div className="text-xs text-muted-foreground">{e.description}</div><div className="mono mt-1 text-[10px] text-muted-foreground">{e.time}</div></div></div>)}</div></div></div></PageFrame>;
}

function SustainabilityPage() {
  const q = useGetSustainability({ query: { queryKey: getGetSustainabilityQueryKey() } });
  const s = q.data;
  return <PageFrame title="Measure what matters." detail="Impact is not a side report. It is the operating proof that good decisions are adding up." action={<Button testId="button-export-impact" variant="outline" onClick={() => window.print()}><ArrowDownRight className="size-4" /> Print impact brief</Button>}>{q.isLoading ? <Loading lines={4} /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><Metric label="Meals redistributed" value={compact(s?.mealsRedistributed)} trend="+18.6% this month" /><Metric label="Waste avoided" value={s?.wasteAvoidedKg ?? 0} suffix="kg" trend="Equivalent to 4.2 bins" accent="accent" /><Metric label="Carbon saved" value={s?.carbonSavedKg ?? 0} suffix="kg CO₂e" trend="Across 6 service days" /><Metric label="Water saved" value={compact(s?.waterSavedLitres)} suffix="L" trend="The quiet multiplier" /><Metric label="Value retained" value={`₹${compact(s?.moneySavedInr)}`} trend={`${s?.successRate ?? 0}% loop success`} /></div><div className="mt-7 grid gap-5 xl:grid-cols-[1.4fr_.6fr]"><div className="panel p-5"><SectionHeader eyebrow="Cumulative signal" title="A week that compounds" detail="Redistributed meals and avoided waste by service window." /><div className="chart-grid relative h-64 rounded-xl border border-border p-5"><div className="absolute inset-x-6 bottom-8 top-8 flex items-end gap-3">{(s?.daily ?? []).map((d, i) => <div key={d.label} className="flex flex-1 items-end gap-1"><div className="flex-1 rounded-t-lg bg-primary/80" style={{ height: `${Math.max(10, (d.meals / Math.max(...(s?.daily ?? []).map((x) => x.meals), 1)) * 84)}%` }} /><div className="flex-1 rounded-t-lg bg-accent/75" style={{ height: `${Math.max(8, (d.waste / Math.max(...(s?.daily ?? []).map((x) => x.waste), 1)) * 68)}%` }} /></div>)}{!(s?.daily?.length) && <div className="absolute inset-0 grid place-items-center text-sm text-muted-foreground">Impact points will appear after the first service window.</div>}<div className="absolute inset-x-6 bottom-2 flex justify-between text-[10px] text-muted-foreground">{(s?.daily ?? []).map((d) => <span key={`${d.label}-axis`}>{d.label}</span>)}</div></div><div className="mt-3 flex gap-4 text-xs text-muted-foreground"><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-primary" /> Meals</span><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-accent" /> Waste avoided</span></div></div><div className="panel overflow-hidden p-5"><SectionHeader eyebrow="Field note" title="Why this reads as progress" /><div className="rounded-2xl bg-secondary/60 p-5"><Leaf className="size-7 text-primary" /><p className="mt-5 text-lg font-medium leading-7">Every meal redirected is a small systems change: less pressure on land, less pressure on budgets, and a fuller table somewhere nearby.</p></div><div className="mt-5 space-y-3 text-sm"><div className="flex justify-between border-b border-border pb-3"><span className="text-muted-foreground">Loop success rate</span><span className="font-semibold">{s?.successRate ?? 0}%</span></div><div className="flex justify-between border-b border-border pb-3"><span className="text-muted-foreground">Reporting cadence</span><span className="font-semibold">Daily close</span></div><div className="flex justify-between"><span className="text-muted-foreground">Data confidence</span><Tag kind="good">Measured</Tag></div></div></div></div></div></>}</PageFrame>;
}

function AlertsPage() {
  const q = useGetAlerts({ query: { queryKey: getGetAlertsQueryKey() } });
  const update = useUpdateAlert();
  return <PageFrame title="Resolve the right thing next." detail="Alerts are ordered by consequence and time window, so the team can move without noise." action={<Button testId="button-refresh-alerts" onClick={() => q.refetch()} variant="outline"><RefreshCw className="size-4" /> Refresh feed</Button>}>{q.isLoading ? <Loading lines={5} /> : q.isError ? <ErrorState onRetry={() => q.refetch()} /> : <div className="grid gap-4 xl:grid-cols-[1.25fr_.75fr]"><div className="space-y-3">{(q.data ?? []).map((a) => <AlertRow key={a.id} alert={a} onResolve={() => update.mutate({ id: a.id, data: { status: 'resolved' } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetAlertsQueryKey() }) })} />)}{!(q.data?.length) && <Empty title="The alert queue is clear" detail="Nothing is asking for an operator right now." />}</div><div className="panel p-5"><SectionHeader eyebrow="Signal hygiene" title="How to use this queue" /><div className="space-y-4 text-sm"><div className="flex gap-3"><span className="mt-1 size-2 rounded-full bg-destructive" /><div><div className="font-semibold">Critical</div><p className="mt-1 text-xs leading-5 text-muted-foreground">Protect a food safety or pickup window now.</p></div></div><div className="flex gap-3"><span className="mt-1 size-2 rounded-full bg-accent" /><div><div className="font-semibold">Watch</div><p className="mt-1 text-xs leading-5 text-muted-foreground">A trend is moving toward a decision boundary.</p></div></div><div className="flex gap-3"><span className="mt-1 size-2 rounded-full bg-primary" /><div><div className="font-semibold">Resolved</div><p className="mt-1 text-xs leading-5 text-muted-foreground">Kept in the record for shift handoff and learning.</p></div></div></div></div></div>}</PageFrame>;
}

function SettingsPage() {
  const reset = useResetDemo();
  const simulate = useSimulateDemo();
  const [message, setMessage] = useState('');
  const run = (action: any) => simulate.mutate({ data: { action } }, { onSuccess: (result) => { setMessage(result.message); queryClient.invalidateQueries(); } });
  return <PageFrame title="Make the demo yours." detail="Change the conditions, watch the command center respond, and keep assumptions visible to every operator."><div className="grid gap-5 xl:grid-cols-[1fr_.8fr]"><div className="panel p-5 md:p-6"><SectionHeader eyebrow="Scenario controls" title="Create a live condition" detail="These controls call the simulation layer; they do not fake an operational state." /><div className="grid gap-3 sm:grid-cols-2">{[{ action: DemoInputAction.temperature_spike, label: 'Temperature spike', detail: 'Raise a cold-zone risk signal', icon: Thermometer }, { action: DemoInputAction.new_surplus, label: 'New surplus batch', detail: 'Add safe food to the matching queue', icon: PackageCheck }, { action: DemoInputAction.accept_match, label: 'Accept next match', detail: 'Move a partner match into pickup planning', icon: Users }, { action: DemoInputAction.complete_delivery, label: 'Complete delivery', detail: 'Close a route and record impact', icon: Truck }, { action: DemoInputAction.advance_time, label: 'Advance service clock', detail: 'Move the demo to its next window', icon: Clock3 }].map(({ action, label, detail, icon: Icon }) => <button key={action} data-testid={`button-simulate-${action}`} onClick={() => run(action)} disabled={simulate.isPending} className="group rounded-2xl border border-border bg-background/50 p-4 text-left hover:-translate-y-0.5 hover:border-primary/50 hover:bg-primary/[.03]"><div className="flex items-center justify-between"><span className="grid size-9 place-items-center rounded-xl bg-secondary text-primary"><Icon className="size-4" /></span><ChevronRight className="size-4 text-muted-foreground transition-transform group-hover:translate-x-1" /></div><div className="mt-4 text-sm font-semibold">{label}</div><div className="mt-1 text-xs text-muted-foreground">{detail}</div></button>)}</div>{message && <div className="mt-5 rounded-xl bg-primary/10 p-3 text-sm font-medium text-primary" data-testid="text-demo-message">{message}</div>}</div><div className="panel p-5 md:p-6"><SectionHeader eyebrow="Assumptions" title="What this workspace believes" /><div className="space-y-4 text-sm"><div className="flex items-start gap-3"><ShieldCheck className="mt-0.5 size-4 text-primary" /><div><div className="font-semibold">Food safety first</div><p className="mt-1 text-xs leading-5 text-muted-foreground">Expired or high-risk stock never enters a match without an operator decision.</p></div></div><div className="flex items-start gap-3"><Database className="mt-0.5 size-4 text-primary" /><div><div className="font-semibold">Measured, not guessed</div><p className="mt-1 text-xs leading-5 text-muted-foreground">Forecasts expose confidence ranges and every impact number carries a source window.</p></div></div><div className="flex items-start gap-3"><Zap className="mt-0.5 size-4 text-primary" /><div><div className="font-semibold">Demo state is reversible</div><p className="mt-1 text-xs leading-5 text-muted-foreground">Reset returns the workspace to its original scenario for a clean walkthrough.</p></div></div></div><div className="mt-8 border-t border-border pt-5"><Button testId="button-reset-demo" onClick={() => reset.mutate(undefined, { onSuccess: (result) => { setMessage(result.message); queryClient.invalidateQueries(); } })} variant="danger" disabled={reset.isPending}><RefreshCw className="size-4" /> {reset.isPending ? 'Resetting…' : 'Reset demo state'}</Button></div></div></div></PageFrame>;
}

function AppRouter() {
  return <Shell><Switch><Route path="/" component={OverviewPage} /><Route path="/forecast" component={ForecastPage} /><Route path="/inventory" component={InventoryPage} /><Route path="/surplus" component={SurplusPage} /><Route path="/logistics" component={LogisticsPage} /><Route path="/operations" component={OperationsPage} /><Route path="/sustainability" component={SustainabilityPage} /><Route path="/alerts" component={AlertsPage} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></Shell>;
}
function App() {
  return <QueryClientProvider client={queryClient}><AppRouter /></QueryClientProvider>;
}
export default App;